  ('az-parts-of-speech', 'azerbaycan-dili', 'Nitq hissələri', 'İsim, sifət, say, əvəzlik, feil və zərf — sözlərin mənaca qrupları.', 1)
insert into lessons (id, unit_id, title, intro, visual, sections, sort_order) values
  ('az-u1-l1', 'az-parts-of-speech', 'İsim', 'İsim əşyaların adıdır.', 'noun-cards', '[{"heading":"İsim nədir?","body":"İsim əşyaların, insanların, canlıların və yerlərin adını bildirən nitq hissəsidir."},{"heading":"kim? / nə?","body":"Canlılar ''kim?'' sualına cavab verir (uşaq, quş). Cansız əşyalar ''nə?'' sualına cavab verir (alma, kitab)."},{"heading":"Ümumi və xüsusi isim","body":"Ümumi isim ortaq adı bildirir (şəhər, çay). Xüsusi isim konkret addır və həmişə böyük hərflə yazılır (Bakı, Nigar)."}]'::jsonb, 0),
  ('az-u1-l2', 'az-parts-of-speech', 'Sifət', 'Sifət əşyanın necə olduğunu bildirir.', 'adjective-apple', '[{"heading":"Sifət nədir?","body":"Sifət əşyanın əlamətini, keyfiyyətini və ya rəngini bildirən nitq hissəsidir."},{"heading":"Suallar","body":"Sifət ''necə?'' və ''hansı?'' suallarına cavab verir və çox zaman ismin yanında işlənir (qırmızı alma)."},{"heading":"Nümunələr","body":"Sifət rəngi (ağ), ölçünü (böyük), dadı (şirin) və formanı (yumru) bildirə bilər."}]'::jsonb, 1),
  ('az-say', 'az-parts-of-speech', 'Say', 'Say əşyanın miqdarını və ya sırasını bildirir.', null, '[{"heading":"Say nədir?","body":"Say əşyanın miqdarını və ya sırasını bildirən nitq hissəsidir."},{"heading":"Növləri","body":"Miqdar sayı miqdarı bildirir (bir, iki, on) və ''neçə?'' sualına cavab verir. Sıra sayı sıranı bildirir (birinci, ikinci) və ''neçənci?'' sualına cavab verir."}]'::jsonb, 2),
  ('az-evezlik', 'az-parts-of-speech', 'Əvəzlik', 'Əvəzlik ismin, sifətin yerində işlənir.', null, '[{"heading":"Əvəzlik nədir?","body":"Əvəzlik ismi, sifəti və ya sayı əvəz edən nitq hissəsidir."},{"heading":"Şəxs əvəzlikləri","body":"mən, sən, o, biz, siz, onlar — şəxs əvəzlikləridir."}]'::jsonb, 3),
  ('az-u1-l3', 'az-parts-of-speech', 'Feil', 'Feil hərəkəti bildirir.', 'verb-timeline', '[{"heading":"Feil nədir?","body":"Feil əşyanın hərəkətini və ya iş prosesini bildirən nitq hissəsidir (qaçmaq, yazmaq, gülmək)."},{"heading":"Suallar","body":"Feil ''nə etdi?'', ''nə edir?'', ''nə edəcək?'' kimi suallara cavab verir."},{"heading":"Zaman","body":"Feillər zamana görə dəyişir: yazdı (keçmiş), yazır (indiki), yazacaq (gələcək)."}]'::jsonb, 4),
  ('az-zerf', 'az-parts-of-speech', 'Zərf', 'Zərf hərəkətin tərzini, zamanını və yerini bildirir.', null, '[{"heading":"Zərf nədir?","body":"Zərf feilin əlamətini — hərəkətin tərzini, zamanını, yerini və ya səbəbini bildirən nitq hissəsidir."},{"heading":"Suallar","body":"Zərf ''necə?'', ''nə vaxt?'', ''harada?'' və ''nə üçün?'' suallarına cavab verir."},{"heading":"Növləri","body":"Tərzi-hərəkət zərfi (tez, yavaş), zaman zərfi (dünən, indi, sabah) və yer zərfi (irəli, geri, burada) olur."}]'::jsonb, 5)
